function slug(s){ return String(s).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); }
var BUNDLES = RAW_BUNDLES.map(function(b){
  var out = {id:b.id, room:b.room, set:b.set, name:b.name, need:b.need, reward:b.reward, slot:b.slot||'', note:b.note||'', items:[]};
  b.items.forEach(function(it){
    var name = it[0], qty = it[1]||1, q = it[2]||'', idOverride = it[3];
    var info = ITEM_INFO[name] || {cat:'other', season:'any', how:''};
    out.items.push({id:idOverride || slug(name)+(q?'-'+q:''), name:name, qty:qty, q:q, cat:info.cat, season:info.season, how:info.how, time:info.time||'', weather:info.weather||'', risk:info.risk||''});
  });
  return out;
});
